import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.CDU0sSpB.js";const u=JSON.parse('{"title":"Phase 2–6 Delivery Status","description":"Verified capabilities, evidence, local substitutes, and deliberately unfinished work.","frontmatter":{"title":"Phase 2–6 Delivery Status","description":"Verified capabilities, evidence, local substitutes, and deliberately unfinished work.","outline":[2,3]},"headers":[],"relativePath":"en/delivery/status.md","filePath":"en/delivery/status.md","lastUpdated":1794015952000}'),n={name:"en/delivery/status.md"};function s(i,e,d,c,l,p){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="phase-2–6-delivery-status" tabindex="-1">Phase 2–6 Delivery Status <a class="header-anchor" href="#phase-2–6-delivery-status" aria-label="Permalink to &quot;Phase 2–6 Delivery Status&quot;">​</a></h1><p>Checked on 2026-11-07. This page records only what the current code and real runs can prove; a page existing is not treated as a completed loop.</p><h2 id="phase-result" tabindex="-1">Phase result <a class="header-anchor" href="#phase-result" aria-label="Permalink to &quot;Phase result&quot;">​</a></h2><ul><li><strong>Phase 2: partially complete.</strong> Local files, knowledge bases, public web, document and spreadsheet extraction, task source references, and the draft → approval → local outbox write → receipt loop are usable. Email and calendar accounts, real sending, and external system writes are not implemented, so Phase 2 is not accepted as a whole.</li><li><strong>Phase 3: partially complete.</strong> A same-machine Windows device can pair, approve capabilities individually, observe, pause, resume, take over, hand back, terminate, and run low-risk click, type, key, and UI Automation actions against an explicitly approved target app. Sensitive-area masking, isolated desktops, high-risk actions, snapshots, and compensation are not implemented, so Phase 3 is not accepted as a whole.</li><li><strong>Phase 4: partially complete.</strong> Proactive suggestions, the proactive inbox, accept/ignore/snooze/convert actions, the attention budget, and pause controls form a code loop. Mobile web, phone pairing, push, and remote takeover are not implemented, so Phase 4 is not complete.</li><li><strong>Phase 5: partially complete.</strong> Memory candidates, recall, correction, conflicts, forget propagation, and export, plus method generation, trial evidence, evaluation, promotion, rejection, and rollback, form a code loop. Real long-term memory use, production before/after method comparisons, and full 5.4 acceptance are still missing.</li><li><strong>Phase 6: partially complete.</strong> Incremental event sync, peer authentication, conflict handling, task leases with epoch fencing, device revocation and token rotation, the kill switch, encrypted database backup and restore, health checks, maintenance, and redacted diagnostics form a code loop. Real two-device switching, a lost-device drill, complete migration, weeks of continuous operation, and v1.0 release acceptance are still missing.</li></ul><h2 id="agent-runtime-loop" tabindex="-1">Agent runtime loop <a class="header-anchor" href="#agent-runtime-loop" aria-label="Permalink to &quot;Agent runtime loop&quot;">​</a></h2><ul><li><strong>Implemented:</strong> <code>native</code> and <code>codex</code> executors are peers; executor identity is recorded in runs and artifact manifests. General tasks default to native, explicit code/engineering tasks use Codex, and failures do not silently switch executors.</li><li><strong>Implemented:</strong> Four model protocols (OpenAI Chat, OpenAI Responses, Anthropic Messages, Gemini) with normalized streaming text and tool calls; providers can be selected or customized in settings.</li><li><strong>Implemented:</strong> A <code>@hearth/agent-runtime</code> single-agent tool loop covering read, search, write, edit, patch, shell, web fetch, ask-user, and finish tools, with task-scoped roots, hosts, and tool allowlists.</li><li><strong>Implemented:</strong> Turn, tool-call, token, and duration budgets; checkpoints after model turns and tool steps; recovery with user follow-up; and up to two repair rounds with prior agent context when declared deliverables are missing.</li><li><strong>Implemented:</strong> Tasks requiring network access or engineering workspace writes create a chat proposal and enter the queue only after confirmation. Ordinary general tasks dispatch directly.</li><li><strong>UI contract:</strong> The task list shows executor, phase, tokens, duration, and result. Details show the final summary and declared artifacts first; intermediate JSON, command logs, and checkpoints remain folded technical details.</li></ul><p>This is a code-and-test loop, not evidence of long-running acceptance with real users.</p><h2 id="phase-2-capabilities" tabindex="-1">Phase 2 capabilities <a class="header-anchor" href="#phase-2-capabilities" aria-label="Permalink to &quot;Phase 2 capabilities&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Status</th><th>Implemented</th><th>Deliberately unfinished</th></tr></thead><tbody><tr><td>2.1 Read-only sources</td><td>Partial</td><td>Local file, knowledge, and public web sources; host allowlists; source status, read time, errors, incremental reads, deduplication, disconnect, reconnect, and clear</td><td>Email and calendar only show “needs configuration”; no credentials, reads, or permission verification</td></tr><tr><td>2.2 Documents, tables, and web material</td><td>Basic loop complete</td><td>TXT, Markdown, CSV, JSON, HTML, PDF, DOCX, and XLSX extraction; page, paragraph, sheet, range, and gap metadata; web snapshots and source items can be reviewed</td><td>Complex layouts, OCR for scans, page-level citation navigation, and spreadsheet formula fidelity are not implemented</td></tr><tr><td>2.3 Draft, approval, and external write</td><td>Partial</td><td>Editable, savable, and discardable drafts; one-time short-lived approval; approved effects write to the local outbox with a receipt; rejection and expiry update the draft</td><td>Only writes local <code>.hearth/outbox</code> files and does not contact mail servers; calendar and other external writes are absent</td></tr><tr><td>2.4 Everyday-content acceptance</td><td>Not complete</td><td>Automated tests and isolated-instance checks cover local sources, extraction, and the outbox loop</td><td>No 10–15 real everyday tasks, time, accuracy, recovery, or willingness-to-reuse acceptance</td></tr></tbody></table><p>The local outbox is not presented as a fake success: the UI states that it only writes locally and does not send to recipients. It must not be described as sent before a real mail account is connected.</p><h2 id="phase-3-capabilities" tabindex="-1">Phase 3 capabilities <a class="header-anchor" href="#phase-3-capabilities" aria-label="Permalink to &quot;Phase 3 capabilities&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Status</th><th>Implemented</th><th>Deliberately unfinished</th></tr></thead><tbody><tr><td>3.1 Connect and inspect a device</td><td>Partial</td><td>Six-digit pairing code, device token, pairing approval separate from capability approval, per-capability grants, app allowlist, online state, and device revocation</td><td>No tray or always-visible global “auto control” indicator; Windows same-machine helper only</td></tr><tr><td>3.2 Observe and take over</td><td>Partial</td><td>Session-bound screenshots; pause, resume, takeover, hand back, and terminate; takeover cancels queued input and advances the control epoch; user-idle check; two-minute screenshot expiry</td><td>Sensitive-area masking, long recordings, and complete desktop snapshots are absent</td></tr><tr><td>3.3 Tiered desktop actions</td><td>Partial</td><td>Target-app binding and focus revalidation; click, short text, Enter/Tab/Escape/Ctrl+S; allowlisted UIA invoke/setvalue; UWP host windows mapped to an approved app through their UIA child process; command status and result records; structured rejection</td><td>High-risk preview and confirmation, isolated desktop, snapshots, compensation, and real UIA setvalue acceptance are not complete</td></tr><tr><td>3.4 Desktop acceptance</td><td>Not complete</td><td>Isolated-port checks cover pairing, capability approval, observation, pause, resume, takeover, hand back, and the pro view</td><td>No five real desktop tasks, success-rate, takeover-count, and failure-drill acceptance</td></tr></tbody></table><p>The Windows helper currently focuses the server-approved target app before capture or input; it does not claim reliable background input. For UWP apps hosted by <code>ApplicationFrameHost</code>, the helper reads the window&#39;s UIA subtree and permits focus or capture only when a child process can be resolved to the approved app. For example, <code>CalculatorApp</code> maps to the approved name <code>calculator</code>. If ownership is ambiguous or the child process cannot be read, the helper fails closed instead of treating the host window as the target. Real UIA invocation was verified in Calculator: invoking “2” returned <code>InvokePattern</code> and changed the display from <code>7</code> to <code>72</code>. The same path also completed observe → UIA action → automatic observation through an isolated paired device, with both command results and frame uploads succeeding.</p><h2 id="phase-4-capabilities" tabindex="-1">Phase 4 capabilities <a class="header-anchor" href="#phase-4-capabilities" aria-label="Permalink to &quot;Phase 4 capabilities&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Status</th><th>Implemented</th><th>Deliberately unfinished</th></tr></thead><tbody><tr><td>4.1 Triggers and proactive suggestions</td><td>Code loop complete</td><td>Six trigger families: a task entering the 24-hour deadline window, a failed or recoverable task, an uncertain external effect, an approval pending for more than two hours, new source items in the last 24 hours, and queue backlog or long-running tasks; suggestions include source, why-now, suggested action, expected impact, estimated cost, risk, approval requirement, and priority; one deduplicated row accumulates repeated occurrences</td><td>Email and calendar triggers are disabled placeholders without account reads; proactive mode only produces suggestions and does not execute high-risk actions</td></tr><tr><td>4.2 Proactive inbox</td><td>Code loop complete</td><td>A dedicated priority-ordered inbox supports accept, ignore, snooze, and convert-to-task; accept and convert are separate, where accept only records the decision and convert only creates a queued task without approving approvals or replaying external effects; an ignored event is not rephrased and pushed again</td><td>No multi-device or mobile inbox; no notification-channel delivery, only the local web inbox</td></tr><tr><td>4.3 Phone viewing, approval, and takeover</td><td>Not implemented</td><td>None</td><td>No phone PWA, phone pairing, push, mobile approval, or remote takeover; the current entrance is the same-machine web control plane only</td></tr><tr><td>4.4 Attention budget and proactive acceptance</td><td>Partial</td><td>Daily limit 0–50, quiet hours, cooldown, aggregation window, temporary pause and resume; the budget snapshot shows used-today, limit, quiet/paused state, and next-allowed time; the last seven days count deliveries, accepts, ignores, conversions, and completed tasks; the “Needs You” page collects pending approvals</td><td>No 5–10 real proactive tasks proving at most one interruption per task on average; no push delivery metrics or long-term user-feel record</td></tr></tbody></table><p>The key Phase 4 boundary is that a suggestion is not an execution. <code>accept</code> only changes the suggestion state. Only <code>convert</code> creates a new queued task, and that task still follows the normal executor, approval, and effect-ledger rules. A high-risk action does not bypass approval because it arrived as a proactive suggestion.</p><h2 id="phase-5-capabilities" tabindex="-1">Phase 5 capabilities <a class="header-anchor" href="#phase-5-capabilities" aria-label="Permalink to &quot;Phase 5 capabilities&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Status</th><th>Implemented</th><th>Deliberately unfinished</th></tr></thead><tbody><tr><td>5.1 Visible memory</td><td>Code loop complete</td><td>Memory first enters candidate state and participates in recall only after confirmation; records include kind, subject key, scope, tags, source, confidence, sensitivity, validity, and version; recall scores task relevance and records reasons and usage audits; injected context is marked <code>trusted=&quot;false&quot;</code> and cannot expand authority; recall has item and character budgets</td><td>Auto-capture is off by default and only captures an “experience” memory from a terminal task; no automatic extraction of user facts from email, web pages, or arbitrary documents</td></tr><tr><td>5.2 Correct, forget, and export</td><td>Code loop complete</td><td>Corrections create a new version and retain history; a same-subject conflict is not silently overwritten and requires left, right, or merge resolution; forgetting turns the current record into a tombstone and redacts historical versions, related events, and matching terms in recall audits; export excludes forgotten content; sensitive memory is not recalled by default and <code>secret</code> memory is never recalled</td><td>Cross-device forgetting relies on sync filtering and the local-replica boundary; there is no remote erasure of old copies already exported outside Hearth</td></tr><tr><td>5.3 Summarize and evaluate reusable methods</td><td>Code loop complete</td><td>Candidates are generated from terminal task traces; capabilities are the intersection of source-task capabilities and cannot expand; baseline/trial metrics record success rate, duration, tokens, and approvals; evaluation distinguishes improved, flat, regressed, and insufficient; only candidates with improvement evidence and trial samples can be promoted; rejection and rollback retain reasons and audit</td><td>A “trial” only rereads existing terminal traces as evidence and does not execute a task again for evaluation, so it is not a live shadow executor; no long-term production comparison of an adopted method</td></tr><tr><td>5.4 Memory and evolution acceptance</td><td>Not complete</td><td>API, service, and page-loop tests cover create, confirm, recall, correct, conflict, forget, export, trial, promote, and rollback</td><td>No real-user wrong-memory or wrong-method drills, no before/after success-rate, human-time, and cost comparison, and no full production “propose—evaluate—trial—adopt—revert” acceptance</td></tr></tbody></table><p>The shared boundary is “candidate before confirmation; evidence before promotion.” A candidate method does not go live automatically, and memory content cannot act as an instruction that directly expands tools, network, or approval authority.</p><h2 id="phase-6-capabilities" tabindex="-1">Phase 6 capabilities <a class="header-anchor" href="#phase-6-capabilities" aria-label="Permalink to &quot;Phase 6 capabilities&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Status</th><th>Implemented</th><th>Deliberately unfinished</th></tr></thead><tbody><tr><td>6.1 Multi-device sync and switching</td><td>Partial</td><td>Each instance has its own <code>instanceId</code>; a sync peer token is shown once and stored as a hash plus an encrypted copy; event pages are pulled incrementally by sequence and deduplicated; imported events can rebuild projections; newer local task, memory, or method state is not silently overwritten, and conflicts preserve both sides for a local/remote choice; the sync UI shows peers, cursors, errors, and conflicts</td><td>Only filtered event projections are synchronized; approvals, sources, outbox, devices, desktop, security, sync events, and sensitive/secret memories are not copied; artifact bodies, workspaces, and local absolute paths are not synchronized; no two-real-device switch or offline recovery acceptance</td></tr><tr><td>6.2 Device revocation and safe migration</td><td>Partial</td><td>Task leases carry a TTL, owner, and epoch; after expiry another instance can take over and advance the epoch, and the old owner&#39;s commits and results are rejected; device capabilities can be revoked, device tokens rotated, and devices re-paired; sync peers can rotate tokens or be revoked; the global kill switch blocks approvals and scheduler restart and records a security audit; the security page shows state and audits</td><td>No dedicated cross-device artifact/workspace migration; no real lost-device drill proving a revoked old device cannot approve, take over, or read; clearing the global stop does not auto-restart the executor and requires an explicit user start</td></tr><tr><td>6.3 Backup, restore, and upgrade</td><td>Partial</td><td>Creates a <code>*.hearth-backup</code> encrypted archive; the passphrase is derived with scrypt (N=32768, r=8, p=1), encrypted with AES-256-GCM, minimum 12 characters; the archive contains a SQLite snapshot, required settings/audit/event metadata, and the encrypted local <code>master.key</code>; restore writes a temporary SQLite database, checks <code>user_version</code>, schema, and <code>integrity_check</code>, rebuilds projections, then copies in a transaction with rollback on failure; preserves the current <code>instanceId</code>, <code>createdAt</code>, and global-stop state while clearing old leases, pairings, and desktop-session temporary records; legacy <code>/api/backup</code> returns <code>410</code> and requires encrypted backup</td><td>Excludes artifact bodies, task workspaces, source bodies, outbox attachments, screenshots/desktop temporary files, and external service data, so it is not a complete migratable backup; no application-version upgrade pipeline or failed-upgrade rollback release flow; incompatible schemas are rejected, but no real cross-version fixture drill exists</td></tr><tr><td>6.4 Long-running operation and v1.0 acceptance</td><td>Partial</td><td>Health includes uptime, memory, disk, schema, task counts, scheduler, approvals, kill switch, and the latest maintenance run; maintenance expires stale approvals, recovers interrupted tasks, removes expired leases/desktop commands/screenshots/pairings and temporary files, and does not delete tasks, memories, or artifacts; maintenance runs automatically every six hours after startup and can be triggered manually; a failed maintenance run is recorded and marks health degraded; diagnostics export health, maintenance, counts, and event types without paths, keys, or environment secrets; the operations page shows health, maintenance, and backup boundaries</td><td>No multi-week continuous run, resource-drift data, real v1.0 install/upgrade/migration/exit acceptance, or complete all-task-type regression matrix</td></tr></tbody></table><p>The backup boundary must remain visible in the UI: a recoverable database is not a migrated set of artifact files. After restore, tasks may return, but artifact bodies, task workspaces, or external attachments still require separate backup and verification.</p><h2 id="borrowed-patterns-and-tradeoffs" tabindex="-1">Borrowed patterns and tradeoffs <a class="header-anchor" href="#borrowed-patterns-and-tradeoffs" aria-label="Permalink to &quot;Borrowed patterns and tradeoffs&quot;">​</a></h2><ul><li><strong>OpenClaw:</strong> pairing is separate from capability approval; commands are declared per device and approved individually; an observation frame is the basis for actions; takeover cancels queued input and advances the control epoch; unsupported actions fail closed. Hearth adopts these boundaries.</li><li><strong>Hermes:</strong> explicit capability manifests, target revalidation before execution, and session isolation. Hearth adopts app allowlists and target/epoch checks. It does not claim background focus-free input because the current Windows layer cannot reliably prove input still lands in the approved window.</li><li><strong>OpenClaw proactive-service pattern:</strong> suggestions are separate from execution, and a suggested action returns to the normal approval chain. Hearth adopts this and has not turned proactive suggestions into an auto-executor.</li><li><strong>Hermes health-check pattern:</strong> expose drivers, permissions, runtime state, and the latest maintenance result explicitly. Hearth uses health snapshots, maintenance records, and redacted diagnostics for this boundary.</li><li><strong>DeerFlow:</strong> task decomposition, method candidates, and layered evaluation are design references only. Hearth does not integrate DeerFlow or adopt its multi-agent runtime.</li><li><strong>LoopX:</strong> only small-loop commits, status evidence, and acceptance boundaries are used as delivery-method references; LoopX is not a runtime dependency.</li></ul><h2 id="verification-evidence" tabindex="-1">Verification evidence <a class="header-anchor" href="#verification-evidence" aria-label="Permalink to &quot;Verification evidence&quot;">​</a></h2><p>On 2026-11-07, <code>npm test</code> on the current branch passed all 40 test files and 199 tests; <code>npm run typecheck</code> and <code>npm run build</code> also pass. These checks cover service, API, model-protocol, native tool-loop, budget, permission, checkpoint, and proposal-confirmation code loops but do not replace real-user, real-device, or long-running acceptance. See the <a href="/hearth-os/en/log/day-04.html">Day04 development log</a> for the implementation record.</p><h2 id="remaining-real-acceptance" tabindex="-1">Remaining real acceptance <a class="header-anchor" href="#remaining-real-acceptance" aria-label="Permalink to &quot;Remaining real acceptance&quot;">​</a></h2><ol><li>Read-only email and calendar accounts, real test accounts, and real send receipts.</li><li>Acceptance records for 10–15 everyday content tasks and at least five desktop tasks.</li><li>Sensitive-area masking, isolated desktops, snapshots, compensation, and high-risk actions.</li><li>Real UIA setvalue acceptance and failure drills for lost windows, permission changes, and user takeover.</li><li>Phase 4 phone entry (PWA, pairing, push, remote approval, and takeover), plus interruption acceptance across 5–10 real proactive tasks.</li><li>Phase 5 wrong-memory/wrong-method drills, complete export verification, and real production comparisons before and after method adoption.</li><li>Phase 6 real two-device sync, offline recovery, lost-device revocation, token rotation, backup restore, and migration verification.</li><li>At least several weeks of continuous operation, resource and state-drift checks, an upgrade/rollback pipeline, and overall v1.0 acceptance.</li></ol><p>These gaps are intentionally left open rather than replaced with simulated data or UI that only looks complete.</p>',29)])])}const m=t(n,[["render",s]]);export{u as __pageData,m as default};
